td.script:
(function () {
    var FIELD = 'icon';
    var LIMIT = 300;
    var SVG_NS = 'http://www.w3.org/2000/svg';
    var state = { icons: null, aliases: {}, names: [], shown: [], active: 0 };

    function el(id) {
        return document.getElementById(id);
    }

    function canonical(name) {
        var n = String(name || '').trim().toLowerCase();
        if (!state.icons) {
            return n;
        }
        if (state.icons[n]) {
            return n;
        }
        if (state.aliases[n]) {
            return state.aliases[n];
        }
        return n;
    }

    function svgFor(name) {
        var svg = document.createElementNS(SVG_NS, 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('fill', 'none');
        svg.setAttribute('stroke', 'currentColor');
        svg.setAttribute('stroke-width', '2');
        svg.setAttribute('stroke-linecap', 'round');
        svg.setAttribute('stroke-linejoin', 'round');
        svg.setAttribute('aria-hidden', 'true');
        /* Icon markup is static app data from the lucide sprite, never user input. */
        svg.innerHTML = state.icons[name] || '';
        return svg;
    }

    function currentValue() {
        if (typeof g_form === 'undefined') {
            return '';
        }
        return String(g_form.getValue(FIELD) || '').trim();
    }

    function updatePreview() {
        var value = currentValue();
        var preview = el('rp_ip_preview');
        var label = el('rp_ip_name');
        if (!preview) {
            return;
        }
        while (preview.firstChild) {
            preview.removeChild(preview.firstChild);
        }
        if (!value) {
            label.textContent = 'No icon';
        } else if (!state.icons) {
            label.textContent = value;
        } else if (state.icons[canonical(value)]) {
            preview.appendChild(svgFor(canonical(value)));
            label.textContent = value;
        } else {
            label.textContent = value + ' (not a lucide icon)';
        }
        markSelected();
    }

    function markSelected() {
        var selected = canonical(currentValue());
        var cells = el('rp_ip_grid').childNodes;
        Array.prototype.forEach.call(cells, function (cell) {
            cell.setAttribute('aria-selected', cell.getAttribute('data-name') === selected ? 'true' : 'false');
        });
    }

    function choose(name) {
        if (typeof g_form === 'undefined') {
            return;
        }
        g_form.setValue(FIELD, name);
        updatePreview();
    }

    function focusCell(index) {
        var cells = el('rp_ip_grid').childNodes;
        if (!cells.length) {
            return;
        }
        var i = Math.max(0, Math.min(cells.length - 1, index));
        if (cells[state.active]) {
            cells[state.active].setAttribute('tabindex', '-1');
        }
        state.active = i;
        cells[i].setAttribute('tabindex', '0');
        cells[i].focus();
    }

    function columns() {
        var grid = el('rp_ip_grid');
        var tpl = window.getComputedStyle(grid).gridTemplateColumns || '';
        var n = tpl.split(' ').filter(function (s) {
            return s.length > 0;
        }).length;
        return n || 1;
    }

    function render() {
        var grid = el('rp_ip_grid');
        var q = String(el('rp_ip_search').value || '').trim().toLowerCase();
        var terms = q.split(/\s+/).filter(function (s) {
            return s.length > 0;
        });
        var aliasHits = {};
        Object.keys(state.aliases).forEach(function (alias) {
            var hit = terms.every(function (t) {
                return alias.indexOf(t) >= 0;
            });
            if (hit) {
                aliasHits[state.aliases[alias]] = true;
            }
        });
        var matches = state.names.filter(function (name) {
            if (aliasHits[name]) {
                return true;
            }
            return terms.every(function (t) {
                return name.indexOf(t) >= 0;
            });
        });
        state.shown = matches.slice(0, LIMIT);
        state.active = 0;
        while (grid.firstChild) {
            grid.removeChild(grid.firstChild);
        }
        var selected = canonical(currentValue());
        state.shown.forEach(function (name, i) {
            var cell = document.createElement('button');
            cell.type = 'button';
            cell.className = 'rp-ip-cell';
            cell.setAttribute('role', 'option');
            cell.setAttribute('data-name', name);
            cell.setAttribute('title', name);
            cell.setAttribute('aria-label', name);
            cell.setAttribute('aria-selected', name === selected ? 'true' : 'false');
            cell.setAttribute('tabindex', i === 0 ? '0' : '-1');
            cell.appendChild(svgFor(name));
            grid.appendChild(cell);
        });
        var foot = el('rp_ip_foot');
        if (!matches.length) {
            foot.textContent = 'No icons match "' + q + '".';
        } else if (matches.length > LIMIT) {
            foot.textContent = 'Showing ' + LIMIT + ' of ' + matches.length + ' icons. Type to narrow the list.';
        } else {
            foot.textContent = matches.length + ' icon' + (matches.length === 1 ? '' : 's');
        }
    }

    function onGridKey(event) {
        var target = event.target;
        if (!target.getAttribute('data-name')) {
            return;
        }
        var count = el('rp_ip_grid').childNodes.length;
        var cols = columns();
        var key = event.key;
        var next = -1;
        if (key === 'ArrowRight') {
            next = state.active + 1;
        } else if (key === 'ArrowLeft') {
            next = state.active - 1;
        } else if (key === 'ArrowDown') {
            next = state.active + cols;
        } else if (key === 'ArrowUp') {
            if (state.active - cols >= 0) {
                next = state.active - cols;
            } else {
                el('rp_ip_search').focus();
                event.preventDefault();
                return;
            }
        } else if (key === 'Home') {
            next = 0;
        } else if (key === 'End') {
            next = count - 1;
        } else if (key === 'Escape') {
            el('rp_ip_search').focus();
            event.preventDefault();
            return;
        } else if (key === 'Enter' || key === ' ') {
            choose(target.getAttribute('data-name'));
            event.preventDefault();
            return;
        }
        if (next >= 0) {
            if (count > next) {
                focusCell(next);
            }
            event.preventDefault();
        }
    }

    function onSearchKey(event) {
        if (event.key === 'ArrowDown') {
            focusCell(0);
            event.preventDefault();
        } else if (event.key === 'Enter') {
            /* Enter in the search box picks the first match instead of submitting the form. */
            event.preventDefault();
            if (state.shown.length) {
                choose(state.shown[0]);
            }
        }
    }

    function wire() {
        var grid = el('rp_ip_grid');
        var search = el('rp_ip_search');
        var timer = null;
        search.addEventListener('input', function () {
            window.clearTimeout(timer);
            timer = window.setTimeout(render, 120);
        });
        search.addEventListener('keydown', onSearchKey);
        grid.addEventListener('keydown', onGridKey);
        grid.addEventListener('click', function (event) {
            var cell = event.target.closest ? event.target.closest('.rp-ip-cell') : null;
            if (cell) {
                var cells = Array.prototype.slice.call(grid.childNodes);
                state.active = Math.max(0, cells.indexOf(cell));
                choose(cell.getAttribute('data-name'));
            }
        });
        var control = g_form.getControl(FIELD);
        if (control) {
            control.addEventListener('change', updatePreview, false);
            control.addEventListener('input', updatePreview, false);
        }
    }

    function load() {
        var foot = el('rp_ip_foot');
        var xhr = new XMLHttpRequest();
        xhr.open('GET', '/api/x_312987_portal/rp/icons/lucide', true);
        xhr.setRequestHeader('Accept', 'application/json');
        if (window.g_ck) {
            xhr.setRequestHeader('X-UserToken', window.g_ck);
        }
        xhr.onload = function () {
            if (xhr.status !== 200) {
                foot.textContent = 'Could not load icons (HTTP ' + xhr.status + ').';
                return;
            }
            try {
                var data = JSON.parse(xhr.responseText);
                if (data.result) {
                    data = data.result;
                }
                state.icons = data.icons || {};
                state.aliases = data.aliases || {};
                state.names = Object.keys(state.icons).sort();
            } catch (e) {
                foot.textContent = 'Could not read the icon list.';
                return;
            }
            render();
            updatePreview();
        };
        xhr.onerror = function () {
            foot.textContent = 'Could not load icons.';
        };
        xhr.send();
    }

    function init() {
        if (typeof g_form === 'undefined') {
            return;
        }
        if (!el('rp_icon_picker')) {
            return;
        }
        wire();
        updatePreview();
        load();
    }

    if (typeof addLateLoadEvent === 'function') {
        addLateLoadEvent(init);
    } else if (window.addEventListener) {
        window.addEventListener('load', init);
    }
})();
